// Promise
function fetchUser(id) {
  return fetch(`/api/users/${id}`).then(r => r.json());
}

// async/await
async function loadProfile(id) {
  try {
    const user = await fetchUser(id);
    const posts = await fetch(`/api/users/${id}/posts`).then(r => r.json());
    return { user, posts };
  } catch (err) {
    console.error('Failed:', err);
    return null;
  }
}

