import time

def timer(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        print(f'{func.__name__} took {time.time()-start:.3f}s')
        return result
    return wrapper

@timer
def slow():
    time.sleep(0.5)
    return 'done'

def fib():
